WITH valid AS (SELECT *, CAST(started_at AS DATE) AS started_at_day, TRIM(browser) AS clean_browser FROM sessions WHERE started_at > TIMESTAMP '2024-04-12 01:00:00' AND country IS NOT NULL), kept_keys AS (SELECT device FROM valid EXCEPT ALL SELECT device FROM sessions WHERE device IN ('mobile', 'desktop')), reconciled AS (SELECT s.* FROM valid s JOIN kept_keys k ON s.device = k.device), with_dims AS (SELECT a.*, p.city, p.signup_date, p.email FROM reconciled a LEFT JOIN customers p ON a.customer_id = p.id), stats AS (SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, country, device, MAX(started_at) AS last_started_at, COUNT(*) FILTER (WHERE browser = 'Firefox') AS firefox_rows, COUNT(DISTINCT device) AS distinct_devices, SIZE(COLLECT_SET(device)) AS num_devices, SIZE(COLLECT_SET(browser)) AS num_browsers, COUNT(*) FILTER (WHERE browser = 'Firefox') AS firefox_rows_2, GROUPING(DATE_TRUNC('MONTH', signup_date)) AS grouping_id FROM with_dims GROUP BY CUBE (DATE_TRUNC('MONTH', signup_date), country, device)) SELECT activity_month, country, last_started_at, firefox_rows, distinct_devices, num_browsers, firefox_rows_2, grouping_id FROM stats ORDER BY grouping_id DESC NULLS FIRST;
